using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DiscardDieWithActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/DiscardDieWithActionCustomDescription", order = 0)]
public class DiscardDieWithActionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return Smart.Format(GetDiscardDieFromHandDescription(), 1) + "\n" + Smart.Format(arg0: (battleAction as DiscardWithActionAction).BattleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).LowercaseFirst(), format: base.localizationManager.GetLocalizedIfYouDo());
	}

	public virtual string GetDiscardDieFromHandDescription()
	{
		return base.localizationManager.GetLocalizedDiscardDieFromHand();
	}
}
